import GameManager, { TetrisType, BLOCK_COLORS } from "./GameManager";
import { Cell } from "./Cell";
import { ComboPraiseSystem, PraiseLevel } from "../../game/view/ComboPraiseSystem";

/**
 * 俄罗斯方块游戏控制器类
 * 负责处理用户输入和游戏主循环
 */
export class GameController {
    // 单例实例
    private static _instance: GameController = null;

    // 游戏管理器
    private gameManager: typeof GameManager;

    // 下落定时器ID
    private fallTimerId: number = 0;
    // 渲染相关回调
    private renderCallbacks: {
        drawCurrentTetris: Function,
        drawFixedBlocks: Function,
        drawNextTetris: Function,
        drawHoldTetris: Function,
        updateScore: Function,
        onGameOver: Function,
        onLinesCleared?: Function, // 添加行消除回调
        onBlinkUpdate?: Function // 添加闪烁更新回调
    };
    
    /**
     * 获取GameController单例
     */
    public static getInstance(): GameController {
        if (!this._instance) {
            this._instance = new GameController();
        }
        return this._instance;
    }
    
    /**
     * 构造函数（私有，防止外部实例化）
     */
    private constructor() {
        this.gameManager = GameManager;
    }
    
    /**
     * 初始化渲染回调函数
     * @param renderCallbacks 渲染相关的回调函数集合
     */
    public init(renderCallbacks: {
        drawCurrentTetris: Function,
        drawFixedBlocks: Function,
        drawNextTetris: Function,
        drawHoldTetris: Function,
        updateScore: Function,
        onGameOver: Function,
        onLinesCleared?: Function, // 添加行消除回调
        onBlinkUpdate?: Function // 添加闪烁更新回调
    }): void {
        this.renderCallbacks = renderCallbacks;
        
        // 设置游戏管理器回调
        this.gameManager.setCallbacks({
            onDrawCurrentTetris: this.renderCallbacks.drawCurrentTetris,
            onDrawFixedBlocks: this.renderCallbacks.drawFixedBlocks,
            onDrawNextTetris: this.renderCallbacks.drawNextTetris,
            onDrawHoldTetris: this.renderCallbacks.drawHoldTetris,
            onScoreUpdated: this.renderCallbacks.updateScore,
            onGameOver: this.onGameOver.bind(this),
            onLinesCleared: this.onLinesCleared.bind(this), // 添加行消除回调
            onSpeedChanged: this.updateFallTimer.bind(this), // 添加速度变化回调
            onBlinkUpdate: renderCallbacks.onBlinkUpdate // 添加闪烁更新回调
        });
    }
    
    /**
     * 行消除回调处理
     */
    private onLinesCleared(clearedLines: number, rowPositions: number[] = []): void {
        // 调用渲染层的行消除回调
        if (this.renderCallbacks && this.renderCallbacks.onLinesCleared) {
            this.renderCallbacks.onLinesCleared(clearedLines, rowPositions);
        }
    }
    
    /**
     * 开始游戏
     */
    public startGame(): void {
        // 停止之前的定时器（如果有）
        this.stopFallTimer();
        
        // 调用游戏管理器开始游戏
        this.gameManager.startGame();
        
        // 启动下落定时器
        this.startFallTimer();
    }

    public endGame(): void {
        Laya.timer.clearAll(this);
    }
    
    /**
     * 获取水平放置的方块形状（用于预览区和Hold区）
     * @param tetrisType 方块类型
     * @returns 适合水平展示的方块形状
     */
    public getHorizontalShape(tetrisType: TetrisType): number[][] {
        return this.gameManager.getHorizontalShape(tetrisType);
    }
    
    /**
     * 启动下落定时器
     */
    private startFallTimer(): void {
        const fallInterval = this.gameManager.getFallInterval();
        // 将返回值转换为number类型
        this.fallTimerId = Laya.timer.loop(fallInterval, this, this.onFallTimerTick) as unknown as number;
    }
    
    /**
     * 停止下落定时器
     */
    public stopFallTimer(): void {
        if (this.fallTimerId) {
            Laya.timer.clear(this, this.onFallTimerTick);
            this.fallTimerId = 0;
        }
    }
    
    /**
     * 更新下落定时器间隔
     */
    private updateFallTimer(interval: number): void {
        // 先停止当前定时器
        this.stopFallTimer();
        // 使用新的间隔重新启动定时器
        this.fallTimerId = Laya.timer.loop(interval, this, this.onFallTimerTick) as unknown as number;
    }
    
    /**
     * 下落定时器回调
     */
    private onFallTimerTick(): void {
        this.moveDown();
    }
    
    /**
     * 游戏结束处理
     */
    private onGameOver(): void {
        // 停止定时器
        this.stopFallTimer();
        
        // 调用渲染层的游戏结束回调
        if (this.renderCallbacks && this.renderCallbacks.onGameOver) {
            this.renderCallbacks.onGameOver();
        }
    }
    
    /**
     * 处理键盘输入
     * @param keyCode 键码
     */
    public onKeyDown(keyCode: number): void {
        if (!this.gameManager.isRunning()) return;
        
        switch (keyCode) {
            case Laya.Keyboard.LEFT:
                this.moveLeft();
                break;
            case Laya.Keyboard.RIGHT:
                this.moveRight();
                break;
            case Laya.Keyboard.DOWN:
                this.moveDown();
                break;
            case Laya.Keyboard.UP:
                this.rotate();
                break;
            case Laya.Keyboard.SPACE:
                this.quickDrop();
                break;
            case Laya.Keyboard.L: // Hold功能
                this.holdTetris();
                break;
            case Laya.Keyboard.Y: // 方块上移，底部生成新行
                this.moveBlocksUp();
                break;
            // case Laya.Keyboard.P: // 显示连击效果
            //     ComboPraiseSystem.getInstance().showComboEffectByCount(7);
            //     break;
            //     case Laya.Keyboard.O: // 显示连击效果
            //     ComboPraiseSystem.getInstance().showComboEffectByCount(6);
            //     break;
        }
    }
    
    /**
     * 向左移动当前方块
     */
    public moveLeft(): boolean {
        return this.gameManager.moveLeft();
    }
    
    /**
     * 向右移动当前方块
     */
    public moveRight(): boolean {
        return this.gameManager.moveRight();
    }
    
    /**
     * 向下移动当前方块
     */
    public moveDown(): boolean {
        return this.gameManager.moveDown();
    }
    
    /**
     * 方块上移，底部生成新行
     */
    public moveBlocksUp(clearLines:number): boolean {
        return this.gameManager.moveBlocksUp(clearLines);
    }
    
    /**
     * 旋转当前方块
     */
    public rotate(): boolean {
        return this.gameManager.rotateTetris();
    }
    
    /**
     * 快速下落当前方块
     */
    public quickDrop(): boolean {
        return this.gameManager.quickDrop();
    }
    
    /**
     * Hold功能
     */
    public holdTetris(): boolean {
        return this.gameManager.holdTetris();
    }
    
    /**
     * 打印当前游戏数据
     */
    public printGameData(): void {
        const gameData = this.gameManager.getTetrisGameData();
        console.log("当前俄罗斯方块游戏数据:");
        console.log(JSON.stringify(gameData, null, 2));
    }
    
    /**
     * 获取当前游戏矩阵
     * @returns 游戏矩阵的副本
     */
    public getGameMatrix(): Cell[][] {
        // 直接返回Cell类型的矩阵
        return this.gameManager.getGameMatrix();
    }
    
    /**
     * 检查是否可以移动到指定位置
     * @param shape 方块形状
     * @param x 目标位置x坐标
     * @param y 目标位置y坐标
     * @returns 如果位置有效返回true，否则返回false
     */
    public isValidMove(shape: number[][], x: number, y: number): boolean {
        const offsetX = x - this.getCurrentTetrisInfo().position.x;
        const offsetY = y - this.getCurrentTetrisInfo().position.y;
        return !this.gameManager.isCollision(offsetX, offsetY);
    }
    
    /**
     * 获取当前方块信息
     * @returns 当前方块的类型、颜色、位置和形状
     */
    public getCurrentTetrisInfo() {
        const info = this.gameManager.getCurrentTetrisInfo();
        // 重命名属性，确保与使用位置匹配
        return {
            type: info.type,
            colorIndex: info.color, // 重命名color为colorIndex
            position: info.position,
            shape: info.shape
        };
    }
    
    /**
     * 获取当前速度级别
     */
    public getCurrentSpeedLevel(): number {
        return this.gameManager.getCurrentSpeedLevel();
    }

    /**
     * 获取速度级别总数
     */
    public getSpeedLevelsCount(): number {
        return this.gameManager.getSpeedLevelsCount();
    }

    /**
     * 增加速度级别
     */
    public increaseSpeed(): boolean {
        this.gameManager.increaseSpeed();
        return true;
    }

    /**
     * 减少速度级别
     */
    public decreaseSpeed(): boolean {
        this.gameManager.decreaseSpeed();
        return true;
    }

    /**
     * 设置速度级别
     */
    public setSpeedLevel(level: number): boolean {
        this.gameManager.setSpeedLevel(level);
        return true;
    }

    /**
     * 设置自动上移功能是否启用
     * @param enabled 是否启用
     */
    public setAutoPushEnabled(enabled: boolean): void {
        this.gameManager.setAutoPushEnabled(enabled);
    }

    /**
     * 获取自动上移功能是否启用
     */
    public getAutoPushEnabled(): boolean {
        return this.gameManager.getAutoPushEnabled();
    }
    
    /**
     * 检查游戏是否活跃（运行中且非闪烁状态）
     * @returns 如果游戏活跃返回true，否则返回false
     */
    public isGameActive(): boolean {
        return this.gameManager.isRunning() && !this.gameManager.getBlinkingState();
    }
    
    /**
     * 清理资源
     */
    public dispose(): void {
        this.stopFallTimer();
        // 注意：不要在这里释放GameManager，因为它可能被其他地方使用
    }
    
    /**
     * 重置单例（通常在游戏结束或场景切换时调用）
     */
    public static reset(): void {
        if (this._instance) {
            this._instance.dispose();
            this._instance = null;
        }
    }
}
