const { regClass } = Laya;
import { ImgDialogBase } from "./ImgDialog.generated";

@regClass('RUMV5hpfRdCRzhO9yBDCzg==')
export class ImgDialog extends ImgDialogBase {
    public constructor() {
        super();
    }

    onEnable(): void {
        this.img_show.on(Laya.Event.CLICK, this, this.close);
    }

    public setOpenData(data: any) {
        if (data) {
            this.img_show.skin = data;
        }
    }

    onDisable(): void {}
}
