export enum AssetStatusEnum {
  PendingAudit = 1,
  AuditApproved = 2,
  AuditRejected = 3,
  UploadingChain = 4,
  ContractSuccess = 5,
  ChainFailed = 6,
  PendingRetry = 7,
  InsufficientBalance = 8,
  TokenNotInList = 9,
  Refunded = 10,
}

const statusKeyMap: Record<number, string> = {
  1: 'Pending Audit',
  2: 'Audit Approved',
  3: 'Audit Rejected',
  4: 'Uploading Chain',
  5: 'Contract Success',
  6: 'Chain Failed',
  7: 'Pending Retry',
  8: 'Insufficient Balance',
  9: 'Token Not In List',
  10: 'Refunded',
  11:"Chain Mismatch",
  12:"Contract Success"
};

export function getStatusKeyByValue(value: number): string {
  return statusKeyMap[value] || '';
} 