import { ItemItem } from "../data/sheetItem/item/ItemItem";
import { ItemDto } from "../data/dto/ItemDto";
import { Dictionary } from "../utils/Dictionary";
import { PackageData } from "../data/vo/pack/PackageData";
import Signal from "./event/Signal";
import { GameEvent } from "./event/GameEvent";
import { ItemVo } from "../data/vo/pack/ItemVo";
import { SnakeDto } from "../data/dto/SnakeDto";
import { SnakePackageData } from "../data/vo/pack/SnakePackageData";
import { SnakeVo } from "../data/vo/pack/SnakeVo";

class KnapsackManager {
    private static _instance: KnapsackManager;

    /** 背包物品字典，key为物品ID，value为物品信息 */

    private m_packageData: PackageData;
    private m_snakePackageData: SnakePackageData;

    /**
     * 构造函数
     */
    private constructor() {
        this.m_packageData = new PackageData();
        this.m_snakePackageData = new SnakePackageData();
    }

    /**
     * 获取单例实例
     */
    public static getInstance(): KnapsackManager {
        if (!KnapsackManager._instance) {
            KnapsackManager._instance = new KnapsackManager();
        }
        return KnapsackManager._instance;
    }

    /**
     * 初始化背包数据
     * @param items 背包物品数据数组
     */
    public initKnapsackData(items: ItemDto[]): void {
        this.m_packageData.initData(items);
        Signal.event(GameEvent.EVENT_ITEM_UPDATE);
    }

    /**
     * 更新背包物品数据
     * @param items 需要更新的物品数据数组
     */
    public updateKnapsackItems(items: ItemDto[]): void {
        this.m_packageData.updateData(items);
    }

    /**
     * 获取所有背包物品
     * @returns 背包中所有物品的数组
     */
    public getAllKnapsackItems(): ItemVo[] {
        if (!this.m_packageData.m_dicItemList) {
            return [];
        }
        return this.m_packageData.m_dicItemList.values;
    }

    /**
     * 根据ID获取背包物品
     * @param itemId 物品ID
     * @returns 物品信息，如果不存在则返回null
     */
    public getKnapsackItemById(itemId: number): ItemVo {
        if (!this.m_packageData.m_dicItemList) {
            return null;
        }
        return this.m_packageData.getItemById(itemId);
    }

    /**
     * 获取背包中物品的数量
     * @param itemId 物品ID
     * @returns 物品数量，如果不存在则返回0
     */
    public getKnapsackItemCount(itemId: number): number {
        return this.m_packageData.getCountById(itemId);
    }

    /**
     * 检查背包中是否有指定物品
     * @param itemId 物品ID
     * @returns 是否存在该物品
     */
    public hasKnapsackItem(itemId: number): boolean {
        return this.getKnapsackItemCount(itemId) > 0;
    }

    //=================================================

    /**
     * 初始化背包数据
     * @param items 背包蛇数据数组
     */
    public initSnakeData(items: SnakeDto[]): void {
        this.m_snakePackageData.initData(items);
        Signal.event(GameEvent.EVENT_SNAKE_UPDATE);
    }

    /**
     * 更新背包蛇数据
     * @param items 需要更新的蛇数据数组
     */
    public updateSnakeItems(items: SnakeDto[]): void {
        this.m_snakePackageData.updateData(items);
    }

    /**
     * 获取所有背包蛇
     * @returns 背包中所有蛇的数组
     */
    public getAllSnakeItems(): SnakeVo[] {
        if (!this.m_snakePackageData.m_dicSnakeList) {
            return [];
        }
        return this.m_snakePackageData.m_dicSnakeList.values;
    }

    /**
     * 根据ID获取背包蛇
     * @param unkey 蛇ID
     * @returns 蛇信息，如果不存在则返回null
     */
    public getSnakeItemById(unkey: number): SnakeVo {
        if (!this.m_snakePackageData.m_dicSnakeList) {
            return null;
        }
        return this.m_snakePackageData.getSnakeById(unkey);
    }

    /**
     * 获取背包中蛇的数量
     * @param unkey 蛇ID
     * @returns 蛇数量，如果不存在则返回0
     */
    public getSnakeItemCount(unkey: number): number {
        return this.m_snakePackageData.getCountById(unkey);
    }

    /**
     * 检查背包中是否有指定蛇
     * @param unkey 蛇ID
     * @returns 是否存在该蛇
     */
    public hasSnakeItem(unkey: number): boolean {
        return this.getSnakeItemCount(unkey) > 0;
    }

    /**
     * 检查背包中蛇数量是否足够
     * @param unkey 蛇ID
     * @param count 需要检查的数量
     * @returns 数量是否足够
     */
    public isSnakeItemEnough(unkey: number, count: number): boolean {
        return this.getSnakeItemCount(unkey) >= count;
    }
}
export default KnapsackManager.getInstance();
