// AudioUtils.ts

/**
 * 音频工具
 */
class AudioUtils {
  private static _instance: AudioUtils;

  public static getInstance(): AudioUtils {
    if (AudioUtils._instance == null) {
      AudioUtils._instance = new AudioUtils();
      return AudioUtils._instance;
    } else {
      return AudioUtils._instance;
    }
  }
  swap: string = "swap.mp3"; // 交换音效
  click: string = "click.bubble.mp3"; // 点击音效
  eliminate: string[] = [
    "eliminate1.mp3",
    "eliminate2.mp3",
    "eliminate3.mp3",
    "eliminate4.mp3",
    "eliminate5.mp3",
    "eliminate6.mp3",
    "eliminate7.mp3",
    "eliminate8.mp3",
  ]; // 消除音效
  continuousMatch: string[] = [
    "contnuousMatch3.mp3",
    "contnuousMatch5.mp3",
    "contnuousMatch7.mp3",
    "contnuousMatch9.mp3",
    "contnuousMatch11.mp3",
  ]; // 连续匹配音效

  /**
   * 播放点击音效
   */
  playClick(): void {
    Laya.SoundManager.playSound("resources/music/" + this.click);
  }

  /**
   * 播放交换音效
   */
  playSwap(): void {
    Laya.SoundManager.playSound("resources/music/" + this.swap);
  }

  /**
   * 播放消除音效
   * @param step 消除步骤
   */
  playEliminate(step: number): void {
    step = Math.min(this.eliminate.length - 1, step);
    Laya.SoundManager.playSound("resources/music/" + this.eliminate[step]);
  }

  /**
   * 播放连续匹配音效
   * @param step 连续匹配步骤
   */
  playContinuousMatch(step: number): void {
    step = Math.min(step, 11);
    if (step < 2) return;
    Laya.SoundManager.playSound(
      "resources/music/" + this.continuousMatch[Math.floor(step / 2) - 1]
    );
  }
}

export default AudioUtils.getInstance();
