const { regClass } = Laya;
import { HeadItem } from "../../data/sheetItem/HeadItem";
import { RoleHeadListItemBase } from "./RoleHeadListItem.generated";

@regClass('AwN/JFPwQsKswm1N53Bmkg==')
export class RoleHeadListItem extends RoleHeadListItemBase {
    private headItem: HeadItem;
    public set dataSource(value: any) {
        super.dataSource = value;
        this.headItem = value as HeadItem;
        if (!this.headItem) {
            return;
        }
        this.setCurrentOutPut();
    }

    async setCurrentOutPut() {
        let headId = this.headItem.id;
        this.playerIcon.headSkin = headId;
    }
    onChange(isSelect: boolean) {}
}
