const { regClass } = Laya;
import { SceneType } from "../../common/baseScene/SceneType";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import { LayerManager } from "../../common/LayerManager";
import SceneManager from "../../common/SceneManager";
import { MailVo } from "../../data/vo/pack/MailVo";
import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import { AnimationUtil } from "../../utils/AnimationUtil";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import { TimeUtil } from "../../utils/TimeUtil";
import NoticeMgr from "../notice/NoticeMgr";
import { MailDetailDialogBase } from "./MailDetailDialog.generated";

@regClass('WjTtnnE4SVGLBLwE/SnXkA==')
export class MailDetailDialog extends MailDetailDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;

    private mailVo: MailVo;

    public constructor(_data: any) {
        super();
    }

    setOpenData(datas: any): void {
        this.handleSelectMail(datas);
    }

    onEnable(): void {
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_MAIL_DELETE, this, this.onDeleteResult);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_MAIL_CHECK, this, this.onReadResult);
        // AnimationUtil.startJellyScaleAnimation(this.tf_title);

        this.btn_delete.on(Laya.Event.CLICK, this, this.deleteMail);
        this.btn_receive.on(Laya.Event.CLICK, this, this.onReceiveClick);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_MAIL_GET, this, this.onMailGetBack);
    }

    /**
     * 邮件选择处理逻辑
     * @param index - 被选择邮件的列表索引
     */
    private handleSelectMail(mailItem: any): void {
        this.mailVo = mailItem;

        this.tf_des.text = mailItem.content;
        let time = TimeUtil.formatDayAndTime(mailItem.sendTime);
        this.tf_time.text = `${time.date} ${time.time}`;
        this.tf_title.text = mailItem.title;
        this.tf_from.text = GameLanguageMgr.getLanguage(21, mailItem.sendName);

        if (mailItem.items && mailItem.items.length > 0) {
            this.rewardList.array = mailItem.items;
            this.rewardList.visible = true;
            this.btn_receive.visible = !mailItem.get;
        } else {
            this.rewardList.visible = false;
            this.btn_receive.visible = false;
        }

        // 调用MSG_MAIL_CHECK接口标记邮件已读
        if (mailItem.read == false) {
            const cmdId = com.snake.socket.MessageType.MSG_MAIL_CHECK;
            const requestData = com.snake.socket.CS_MAIL_CHECK.fromObject({ mailId: mailItem.mailId });
            HallWebSocket.send(cmdId, requestData);
        }
    }

    /**
     * 删除结果响应处理
     * @param msgBody - 服务器返回的删除操作结果
     * @param msgcode - 消息响应状态码
     */
    private onDeleteResult(msgBody: any, msgcode: number): void {
        if (msgcode === com.snake.socket.MessageCode.SYS_NORMAL) {
            // 服务器确认删除成功，更新界面
            Signal.event(GameEvent.EVENT_REQUEST_MAIL_DATA); //请求邮件列表数据
            NoticeMgr.notice(GameLanguageMgr.getLanguage(69));
            this.close();
        } else {
            // 删除失败
        }
    }

    /**
     * 已读状态更新回调
     * @param msgBody - 服务器返回的已读状态更新结果
     * @param msgcode - 消息响应状态码
     */
    private onReadResult(msgBody: any, msgcode: number): void {
        if (msgcode === com.snake.socket.MessageCode.SYS_NORMAL) {
            // 服务器确认标记已读成功，更新界面

            Signal.event(GameEvent.EVENT_REQUEST_MAIL_DATA); //请求邮件列表数据
        }
    }

    /**
     * 邮件删除请求方法
     */
    private deleteMail(): void {
        // 调用MSG_MAIL_DELETE接口删除邮件
        if (this.mailVo) {
            const mailItem = this.mailVo;
            const cmdId = com.snake.socket.MessageType.MSG_MAIL_DELETE;
            const requestData = com.snake.socket.CS_MAIL_DELETE.fromObject({ mailId: mailItem.mailId });
            HallWebSocket.send(cmdId, requestData);
        }
    }

    public removeEvent(): void {
        // this.btn_back.off(Laya.Event.CLICK, this, this.setToMainScene);
    }

    private setToMainScene(): void {
        SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
    }

    private onReceiveClick(): void {
        // 发送领取邮件请求
        const cmdId = com.snake.socket.MessageType.MSG_MAIL_GET;
        let mail = this.mailVo;
        const requestData = com.snake.socket.CS_MAIL_GET.fromObject({ mailId: mail.mailId });
        HallWebSocket.send(cmdId, requestData);
    }

    private onMailGetBack(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(70));
            var msgBody: com.snake.socket.SC_MAIL_GET = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_MAIL_GET);
            console.log(msgBody);
            // 找到对应的邮件
            const mailData = this.mailVo;
            if (mailData) {
                // 删除items属性
                mailData.get = true;
                // 重新渲染显示
                this.handleSelectMail(mailData);
            }
        }
    }

    onDisable(): void {
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_MAIL_DELETE, this, this.onDeleteResult);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_MAIL_CHECK, this, this.onReadResult);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_MAIL_GET, this, this.onMailGetBack);
        this.removeEvent();
        this.btn_delete.off(Laya.Event.CLICK, this, this.deleteMail);
        this.btn_receive.off(Laya.Event.CLICK, this, this.onReceiveClick);
    }
}
