        if (this.fastMoveTimer) {
            clearInterval(this.fastMoveTimer);
            this.fastMoveTimer = null;
        }

        // 回收所有方块
        let children = this.blockContainer.numChildren;
        for (let i = children - 1; i >= 0; i--) {
            this.recycleBlock(this.blockContainer.getChildAt(i) as Laya.Sprite);
        }

        // 停止角色动画
        this.stop();
