    /**
     * 创建攻击方块动画
     * @param startRowY 起始行位置
     * @param blockCount 创建的方块数量
     */
    private createAttackBlocks(startRowY: number, blockCount: number = 5, callBack: Laya.Handler): void {
        if (!this.img_boss) return;

        // 计算目标位置（img_boss组件的全局位置）
        let targetPoint = new Laya.Point(this.img_boss.width / 2, this.img_boss.height / 2);
        let targetGlobalPos = this.img_boss.localToGlobal(targetPoint);

        // 计算起始位置（消除行的中心位置）
        let startPoint = new Laya.Point(this.blockContainer.width / 2, this.offsetY + startRowY * (this.BLOCK_SIZE + this.BLOCK_GAP));
        let startGlobalPos = this.blockContainer.localToGlobal(startPoint);

        // 用于跟踪完成的动画数量
        let completedAnimations = 0;

        // 创建多个攻击方块
        for (let i = 0; i < blockCount; i++) {
            // 创建攻击方块
            let attackBlock = this.createAttackBlock();
            if (!attackBlock) continue;

            // 添加到场景根节点
            this.addChild(attackBlock);

            // 设置起始位置（添加随机偏移）
            let offsetX = (Math.random() - 0.5) * 100; // 随机水平偏移
            let offsetY = (Math.random() - 0.5) * 50;  // 随机垂直偏移
            attackBlock.x = startGlobalPos.x + offsetX;
            attackBlock.y = startGlobalPos.y + offsetY;

            // 创建单个动画完成的回调
            let animationCompleteHandler = Laya.Handler.create(this, () => {
                completedAnimations++;
                // 当所有动画都完成时，执行传入的回调
                if (completedAnimations >= blockCount && callBack) {
                    console.log("所有动画完成");
                        this.playAttacked();
                    callBack.run();
                }
            });
            // 创建抛物线动画，每个方块延迟不同时间和不同转弯幅度
            const curvature = 0.5 + Math.random() * 2.0; // 随机转弯幅度 1.5-3.5
            this.createParabolaAnimation(attackBlock, targetGlobalPos, i * 0.1, animationCompleteHandler, curvature);
        }
    }

