import LanguageItem from "../data/sheetItem/language/LanguageItem";
import { Dictionary } from "../utils/Dictionary";
import { ItemItem } from "../data/sheetItem/item/ItemItem";
import { ArenaItem } from "../data/sheetItem/match/ArenaItem";
import { EnumState } from "../data/enumData/EnumState";
import GlobalDataManager from "../global/GlobalDataManager";
import SheetDataManager from "../global/SheetDataManager";
import GameSetting from "../global/GameSetting";

class GameLanguageMgr {
    private constructor() {
        this._lanTypesById = new Dictionary();
        this._lanTypesByType = new Dictionary();
        this._configData = new Dictionary();
        this._configData1 = new Dictionary();
    }

    private _lanTypesById: Dictionary;
    private _lanTypesByType: Dictionary;
    private _configData: any;
    private _configData1: any;
    private static _instance: GameLanguageMgr;

    public static getInstance(): GameLanguageMgr {
        if (!GameLanguageMgr._instance) {
            GameLanguageMgr._instance = new GameLanguageMgr();
        }
        return GameLanguageMgr._instance;
    }

    public errData: any;
    public initErrData(_data: any): void {
        this.errData = _data;
    }

    public getError(id: any): string {
        if (this.errData[id]) return this.errData[id]["words"];
        else {
            console.warn("服务端错误码语言包未配表 错误码：" + id);
            return id;
        }
    }

    public initLanTypes(value: any): void {
        this._lanTypesById = new Dictionary();
        this._lanTypesByType = new Dictionary();
        for (let a in value) {
            let languageItem: LanguageItem = new LanguageItem();
            languageItem.init(value[a]);
            if (parseInt(languageItem.if_open) != 1) {
                continue;
            }
            let ID: number = languageItem.id;
            let type: string = languageItem.type;
            this._lanTypesById.set(ID, languageItem);
            if (type && type != "") {
                this._lanTypesByType.set(type, languageItem);
            }
        }
    }

    public getLanTypes(): Dictionary {
        return this._lanTypesById;
    }

    public getLanIdByType(type: string): number {
        if (this._lanTypesByType) {
            let languageItem: LanguageItem = this._lanTypesByType.get(type);
            if (languageItem) {
                return parseInt(languageItem.id.toString());
            }
        }
        return 1;
    }

    public getLanTypeById(id: number): string {
        if (this._lanTypesById) {
            let languageItem: LanguageItem = this._lanTypesById.get(id);
            if (languageItem) {
                return languageItem.type;
            }
        }
        return "en";
    }

    //初始化普通语言包
    public initConfigLan(value: any): void {
        this._configData = value;
    }

    //初始化普通语言包
    public initConfigLan1(value: any): void {
        this._configData1 = value;
    }

    public initUILan(value: any): void {
        Laya.Text.langPacks = {};
        let key: string;
        for (key in value) {
            let lanValue: string = value[key]["value"];
            Laya.Text.langPacks[key] = lanValue;
        }
    }

    private changeBrToN(value: string): string {
        let reg: RegExp = /<br>/g;
        while (value.indexOf("<br>") != -1) {
            value = value.replace(reg, "\n");
        }
        return value;
    }

    public replacePlaceholder(source: string, args: any[]): string {
        if (source == "") {
            return "";
        }
        let pattern: RegExp = /{(\d+)}/g;
        if (args.length > 0) {
            source = source.replace(pattern, function (): string {
                return args[arguments[1]];
            });
        }
        return this.replaceLanByBR(source);
    }

    public replaceLanByBR(value: string): string {
        let _str: string = value + "";
        return _str;
    }

    /**
     * 获得仅英文文字
     * @param id
     * @param arg
     * @returns
     */
    public getEnglishLanguage(id: any, ...arg: (string | number)[]): string {
        return this.getEnglishLanguageReplace(id, arg);
    }

    private getEnglishLanguageReplace(id: any, replaceArr: any[]): string {
        if (this._configData1 && this._configData1[id]) {
            let _str: string = this._configData1[id].value as string;
            if (_str && _str != "") {
                let str: string = this.replacePlaceholder(_str, replaceArr);
                return str;
            }
        }
        return this.replacePlaceholder(id + "", replaceArr);
    }

    public getLanguage(id: any, ...arg: (string | number)[]): string {
        return this.getLanguageReplace(id, arg);
    }

    public getLanguageReplace(id: any, replaceArr: any[]): string {
        if (this._configData && this._configData[id]) {
            let _str: string = this._configData[id].value as string;
            if (_str && _str != "") {
                let str: string = this.replacePlaceholder(_str, replaceArr);
                return str;
            }
        }
        return this.replacePlaceholder(id + "", replaceArr);
    }

    public getLanguageMulti(value: any, replaceArr: any[]): string {
        console.log("getLanguageMulti", replaceArr);
        if (this._configData && this._configData[value]) {
            let _str: string = this._configData[value].value as string;
            if (_str && _str != "") {
                let str: string = this.replacePlaceholderMulti(_str, replaceArr);
                return str;
            }
        }
        return this.replacePlaceholder(value + "", replaceArr);
    }

    public replacePlaceholderMulti(source: string, args: any[]): string {
        if (source == "") {
            return "";
        }
        let pattern: RegExp = /{(\d+)}/g;
        if (args.length > 0) {
            source = source.replace(pattern, function (): string {
                var arg = args[arguments[1]];

                if (typeof arg === "object") {
                    arg = JSON.parse(arg);
                    arg = GameLanguageMgr.getInstance().parseObj(arg);
                } else if (typeof arg === "string") {
                    try {
                        arg = JSON.parse(arg as string);
                        if (typeof arg === "object") {
                            arg = GameLanguageMgr.getInstance().parseObj(arg);
                        }
                    } catch (e) {}
                }
                return arg;
            });
        }
        return this.replaceLanByBR(source);
    }

    parseObj(arg: any): string {
        if (arg.hasOwnProperty("tableType")) {
            //tableType  1=根据id获取道具表的名字；2=根据id获取战场表的名字；
            if (arg.tableType == 1) {
                var itemItem: ItemItem = SheetDataManager.m_dicItems.get(arg.id);
                if (itemItem) {
                    arg = GameLanguageMgr.getInstance().getLanguage(itemItem.name);
                }
            } else if (arg.tableType == 2) {
                var arenaItem: ArenaItem = SheetDataManager.m_dicArenaDic.get(arg.id);
                if (arenaItem) {
                    arg = GameLanguageMgr.getInstance().getLanguage(arenaItem.name);
                }
            }
        } else {
            arg = GameLanguageMgr.getInstance().getMultiLan(arg);
        }
        return arg;
    }

    public getUILang(text: string, arg1: any = null, arg2: any = null, arg3: any = null, arg4: any = null): string {
        text = Laya.Text.langPacks && Laya.Text.langPacks[text] ? Laya.Text.langPacks[text] : text;
        if (arguments.length > 1) {
            for (let i: number = 0, n: number = arguments.length; i < n; i++) {
                text = text.replace("{" + i + "}", arguments[i + 1]);
            }
        }
        return text;
    }

    public getMultiLan(contents: any) {
        var lanId = parseInt(GlobalDataManager.m_strLanguage.toString());
        var content: string;
        if (contents) {
            content = contents[lanId];
            if (!content) {
                content = contents[EnumState.Lan_en];
            }
        }
        return content;
    }

    public FGM_GetLanguage(): void {
        let callBack = function (str: string): void {
            console.log("initGame->-----------------------------FGM_GetLanguage:==" + str);
            if (str) {
                GameSetting.User_Lan = str;
            }
        };
        let cookieLang: string = Laya.LocalStorage.getItem(GameSetting.COOKIE_CF_LAN);
        if (!cookieLang || cookieLang == "") {
            callBack(this.language);
        } else {
            callBack(cookieLang);
        }
    }

    public get language(): string {
        return "en";
    }

    public FGM_SetLanguage(language: string): void {
        if (language && language != "") {
            Laya.LocalStorage.setItem(GameSetting.COOKIE_CF_LAN, language);
        }
    }

    public dispose(): void {}
}

export default GameLanguageMgr.getInstance();
