import { Collision } from "../collision/Collision";
import DebugLayer from "../DebugLayer";
import FoodManager from "../food/FoodManager";
import SnakeManager from "../snake/SnakeManager";
import FrameAiManager from "./FrameAiManager";
import GameSetting from "../../global/GameSetting";
import MapManager from "../map/MapManager";

class GameAiControl {
    private static instance: GameAiControl | null = null;

    // private gameMap: MapManager;

    /**
     * 获取 GameAiControl 单例实例
     * @param gameLayer 游戏主场景层（Laya.Sprite）
     * @param joystick 摇杆对象（需实现 initJoystick、changeMode、setEventCallBack 等接口）
     */
    public static getInstance(): GameAiControl {
        if (!GameAiControl.instance) {
            GameAiControl.instance = new GameAiControl();
        }
        return GameAiControl.instance;
    }

    /**
     * 1.初始化本地数据
     * @param gameLayer
     */
    init(gameLayer: Laya.Sprite) {
        if (!gameLayer) {
            throw new Error("gameLayer Must Be Not Null");
        }

        SnakeManager.getInstance().init();
        FoodManager.init();

        // 创建蛇层并设置 zOrder
        const snakeLayer = SnakeManager.getInstance().container;
        const foodLayer = FoodManager.container;
        const debugLayer = new Laya.Sprite();

        gameLayer.addChild(foodLayer);
        gameLayer.addChild(snakeLayer);
        gameLayer.addChild(debugLayer);

        debugLayer.addChild(DebugLayer.getInstance());

        FoodManager.init();
    }

    /**
     * 2.创建数据，刷新
     */
    createData() {
        SnakeManager.getInstance().createSnakes();
        FoodManager.createFoodsByData();
    }
    /**
     * 3.启动游戏
     */
    startGame() {
        var snake = SnakeManager.getInstance().selfSnake;
        MapManager.setCurrentHero(snake);

        FrameAiManager.start();
    }

    clearTimer(): void {}

    endTimer(): void {
        FrameAiManager.end();
    }

    public update(frame: number, isLogicSnake: boolean, hasConfirmed: boolean): void {
        // console.log("update: ", frame);
        // MatchModel.instance.clientFrame++;
        SnakeManager.getInstance().updateSnakes(Laya.timer.delta, isLogicSnake, hasConfirmed, true);
        if (!isLogicSnake) {
            MapManager.moveGameWindow();
            // MapManager.move(SnakeManager.getInstance().getSelfSnakePos(isLogicSnake));
            // 调试绘制
            if (GameSetting.needDraw) {
                const debugLayer = DebugLayer.getInstance();
                if (debugLayer) {
                    debugLayer.clearDraw();
                    // const allCollidables = Collision.getInstance(null).getAllCollidables();
                    // debugLayer.updateCollidables(allCollidables);
                    // debugLayer.draw();

                    Collision.getInstance(null).drawDebug(debugLayer.graphics);
                }
            }
        }
    }

    // public createFood(foodObject: com.snake.socket.FoodObject): void {
    //     return FoodManager.addFood(foodObject);
    // }

    clear() {
        this.clearTimer();
        // SnakeManager = null;
        // FoodManager = null;
        // this.gameMap.destroy();
        // this.gameMap = null;
        // GameAiControl.instance = null;
    }
}
export default GameAiControl.getInstance();
