const { regClass } = Laya;
import { ModuleManager } from "../../common/ModuleManager";
import { ModuleName } from "../../global/ModuleName";
import { EnumConsumeType } from "../../data/enumData/EnumConsumeType";
import { EnumItemType } from "../../data/enumData/EnumItemType";
import { ItemVo } from "../../data/vo/pack/ItemVo";
import { KnapsackItem } from "../item/KnapsackItem";
import { MatchRewardListItemBase } from "./MatchRewardListItem.generated";

@regClass('WXpxCvqlQ2mKdcJCYlqOeg==')
export class MatchRewardListItem extends MatchRewardListItemBase {
    public itemVo: ItemVo;
    public showAdd: boolean = false;
    private isAddEvent: boolean = false;
    private oriScale: number = 1;

    public constructor() {
        super();
    }

    onEnable(): void {
        this.oriScale = this.knapsackItem.img_icon.scaleX;
    }
    public createChildren(): void {
        super.createChildren();
        // this.visible = false;
    }

    private addEvent() {
        if (!this.isAddEvent) {
            this.on(Laya.Event.CLICK, this, this.toDetail);
            this.isAddEvent = true;
            // Signal.on(HeroEvent.EVENT_HERO_DRAW_UPDATE_PRODUCTION, this, this.updateProduction);
        }
    }

    public set dataSource(value: any) {
        //console.log("dataSource: ", value);
        super.dataSource = value;
        this.itemVo = value as ItemVo;
        if (!this.itemVo) {
            return;
        }
        this.addEvent();
        this.setCurrentOutPut();
    }

    async setCurrentOutPut() {
        if (!this.itemVo) return;
        if (this.itemVo.id == EnumConsumeType.TYPE_REWARD_TOKEN) {
            this.img_tokens.visible = true;
            this.knapsackItem.visible = false;
        } else {
            this.img_tokens.visible = false;
            this.knapsackItem.visible = true;
            (this.knapsackItem as KnapsackItem).showAdd = true;
            (this.knapsackItem as KnapsackItem).dataSource = this.itemVo;
            var iconScalse = this.oriScale;
            if (this.itemVo.type == EnumItemType.TYPE_TOKEN) {
                iconScalse = this.oriScale * 0.8;
            }
            this.knapsackItem.img_icon.scale(iconScalse, iconScalse);
        }
    }

    private toDetail() {
        if (!this.itemVo || !this.itemVo.needTip) {
            return;
        }
        if (this.itemVo.id == EnumConsumeType.TYPE_REWARD_TOKEN) {
            ModuleManager.intance.openModule(ModuleName.MatchEndRewardTokensDialog);
        } else {
            if (this.itemVo.type === EnumItemType.TYPE_Equipment) {
                ModuleManager.intance.openModule(ModuleName.EquipDetailDialog, this.itemVo);
            } else {
                ModuleManager.intance.openModule(ModuleName.KnapsackTipDialog, this.itemVo);
            }
        }
    }
}
