const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import SoundMgr from "../../common/SoundMgr";
import GlobalDataManager from "../../global/GlobalDataManager";
import SheetDataManager from "../../global/SheetDataManager";
import { AnimationUtil } from "../../utils/AnimationUtil";
import { SettingDialogBase } from "./SettingDialog.generated";

@regClass('Br9XipoESNmBLv+VvZwIdg==')
export class SettingDialog extends SettingDialogBase {
    public m_iLayerType: number;
    public m_iPositionType: number;
    onAwake(): void {
        this.m_iLayerType = LayerManager.M_POP;
        this.m_iPositionType = LayerManager.UP;
    }
    onOpened(datas: any): void {
        //根据参数切换优先显示的类目
    }

    onEnable(): void {
        //注册事件顶部按钮点击（切换蛇）
        for (let i = 0; i < 3; i++) {
            (this as any)["tab" + i].on(Laya.Event.CLICK, this, this.onTabClick, [i]);
        }
        this.btn_music_plus.on(Laya.Event.CLICK, this, this.onClickMusicPlus, [true]);
        this.btn_music_reduce.on(Laya.Event.CLICK, this, this.onClickMusicPlus, [false]);
        this.btn_sound_plus.on(Laya.Event.CLICK, this, this.onClickSoundPlus, [true]);
        this.btn_sound_reduce.on(Laya.Event.CLICK, this, this.onClickSoundPlus, [false]);
        // this.btn_back.on(Laya.Event.CLICK, this, this.setToMainScene);
        this.btn_privacy.on(Laya.Event.CLICK, this, this.onPrivacyClick);
        this.tf_goWeb.on(Laya.Event.CLICK, this, this.onGoWebClick);
        this.btn_copy.on(Laya.Event.CLICK, this, this.onGoWebClick);
        this.btn_service.on(Laya.Event.CLICK, this, this.onServiceClick);
        this.btn_tele.on(Laya.Event.CLICK, this, this.onTeleClick);
        this.btn_youtube.on(Laya.Event.CLICK, this, this.onYoutubeClick);

        // this.initData();
        this.initSettingData();
        this.initLanguageData();
        // AnimationUtil.startJellyScaleAnimation(this.tf_tittle);
    }

    /**
     * 设置Tab的选中状态
     * @param value
     */
    public setTab(value: number) {
        for (let i = 1; i < 3; i++) {
            if (value == i) {
                (this as any)["btn_" + i].getChildByName("selectBox1").visible = true;
                (this as any)["btn_" + i].getChildByName("selectBox2").visible = false;
            } else {
                (this as any)["btn_" + i].getChildByName("selectBox1").visible = false;
                (this as any)["btn_" + i].getChildByName("selectBox2").visible = true;
            }
        }
    }

    private initSettingData(): void {
        //获取当前背景音乐音量,并根据音量设置进度条
        let musicValue = SoundMgr.getMusicVolume();
        this.prog_music.value = musicValue;

        //获取当前音效音量,并根据音量设置进度条
        let soundValue = SoundMgr.getSoundVolume();
        this.prog_sound.value = soundValue;
    }

    // private setToMainScene(): void {
    //     SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
    // }

    public removeEvent(): void {
        for (let i = 0; i < 4; i++) {
            (this as any)["tab" + i].off(Laya.Event.CLICK, this, this.onTabClick, [i]);
        }
        // this.btn_back.off(Laya.Event.CLICK, this, this.setToMainScene);
    }

    /**
     * Tab点击事件处理
     * @param index 被点击的Tab索引
     */
    private onTabClick(index: number) {
        // Tab相关常量定义
        const TAB_COUNT = 3;
        const SKIN_SELECTED = "res/setup/settingNew/img_tab1.png";
        const SKIN_UNSELECTED = "res/setup/settingNew/img_tab2.png";
        const STROKE_COLOR_SELECTED = "#ffffff";
        const STROKE_COLOR_UNSELECTED = "#7fb7ff";
        // 遍历所有Tab按钮
        for (let i = 0; i < TAB_COUNT; i++) {
            // 获取当前Tab按钮和其标题文本组件
            const tab = (this as any)[`tab${i}`];
            const title = tab.getChildByName("tf_tit");

            // 判断当前Tab是否被选中，是否是第一个Tab
            const isSelected = index === i;
            // this.selectItemId = index;
            // 根据Tab位置和选中状态设置不同的皮肤
            tab.skin = isSelected ? SKIN_SELECTED : SKIN_UNSELECTED;

            // 设置文字描边效果：选中时显示描边，未选中时隐藏描边
            title.color = isSelected ? STROKE_COLOR_SELECTED : STROKE_COLOR_UNSELECTED;

            switch (index) {
                case 0:
                    this.box_genred.visible = true;
                    this.box_language.visible = false;
                    this.box_saciel.visible = false;
                    break;
                case 1:
                    this.box_genred.visible = false;
                    this.box_language.visible = true;
                    this.box_saciel.visible = false;
                    break;
                case 2:
                    this.box_genred.visible = false;
                    this.box_language.visible = false;
                    this.box_saciel.visible = true;
                    break;
            }
        }
    }

    /**
     * 点击调节背景音乐大小
     * @param isPlus
     */
    private onClickMusicPlus(isPlus: boolean): void {
        //获取当前背景音乐音量
        let musicValue = SoundMgr.getMusicVolume();
        let addValue = 0.1; // 每次调整10%

        if (isPlus) {
            musicValue = Math.min(1.0, musicValue + addValue);
        } else {
            musicValue = Math.max(0.0, musicValue - addValue);
        }

        // 调整进度条值并保存设置
        this.prog_music.value = musicValue;
        SoundMgr.setMusicVolume(musicValue);
    }

    /**
     * 点击调节音效音量大小
     * @param isPlus
     */
    private onClickSoundPlus(isPlus: boolean): void {
        let soundValue = SoundMgr.getSoundVolume();
        let addValue = 0.1; // 每次调整10%

        if (isPlus) {
            soundValue = Math.min(1.0, soundValue + addValue);
        } else {
            soundValue = Math.max(0.0, soundValue - addValue);
        }

        // 调整进度条值并保存设置
        this.prog_sound.value = soundValue;
        SoundMgr.setSoundVolume(soundValue);
    }

    private initLanguageData(): void {
        // 获取language.json里面的所有数据
        let languageData = SheetDataManager.m_dicLanguage.values;
        if (languageData) {
            // 处理语言数据
            // 筛选一下，只保留if_open为1的内容
            const filteredLanguageData = languageData.filter((item) => item.if_open === 1);
            this.list_language.array = filteredLanguageData;
            this.list_language.renderHandler = new Laya.Handler(this, this.handleSelectLanguage);
            this.list_language.mouseHandler = Laya.Handler.create(this, this.onLanguageItemMouse, null, false);
            let selectIndex = filteredLanguageData.findIndex((item) => item.id === GlobalDataManager.m_strLanguage);
            this.list_language.selectedIndex = selectIndex || 0;
        }
    }
    private handleSelectLanguage(cell: any, index: number): void {
        cell.onChange(this.list_language.selectedIndex == index);
    }

    /**
     * @private
     * 下拉列表的鼠标事件响应函数。
     */
    protected onLanguageItemMouse(e: Event, index: number): void {
        let type: string = e.type;
        if (type === Laya.Event.CLICK) {
            this.list_language.selectedIndex = index;
        }
    }

    private onPrivacyClick(): void {
        // 打开服务条款网页
        window.open("https://drive.google.com/file/d/1JHQmFHsoM2m4qynP0tT2rycXHIm8xX-G/view", "_blank");
    }

    private onGoWebClick(): void {
        // 打开服务条款网页
        window.open("https://cryptoarena.io/", "_blank");
    }
    

    private onServiceClick(): void {
        // 打开服务条款网页
        window.open("https://drive.google.com/file/d/1ktcZ2P7lMKEJDsymetdqUzvWKbF0VR2n/view", "_blank");
    }

    private onTeleClick(): void {
        // 打开Telegram网页
        window.open("https://t.me/cryptoarenaio", "_blank");
    }

    private onYoutubeClick(): void {
        window.open("https://www.youtube.com/@ArenaFi", "_blank");

    }
        

    onDisable(): void {
        // 移除tab点击事件
        for (let i = 0; i < 3; i++) {
            (this as any)[`tab${i}`].off(Laya.Event.CLICK, this, this.onTabClick, [i]);
        }

        // 移除音量调节按钮事件
        this.btn_music_plus.off(Laya.Event.CLICK, this, this.onClickMusicPlus, [true]);
        this.btn_music_reduce.off(Laya.Event.CLICK, this, this.onClickMusicPlus, [false]);
        this.btn_sound_plus.off(Laya.Event.CLICK, this, this.onClickSoundPlus, [true]);
        this.btn_sound_reduce.off(Laya.Event.CLICK, this, this.onClickSoundPlus, [false]);
        this.btn_tele.off(Laya.Event.CLICK, this, this.onTeleClick);
        this.btn_youtube.off(Laya.Event.CLICK, this, this.onYoutubeClick);
        // 移除返回按钮事件
        // this.btn_back.off(Laya.Event.CLICK, this, this.setToMainScene);

        // 移除语言列表事件
        if (this.list_language) {
            this.list_language.mouseHandler.clear();
        }

        // 清理所有定时器
        Laya.timer.clearAll(this);
    }
}
