import { TokenData } from "../data/dto/TokenData";
import { GameEvent } from "../global/event/GameEvent";
import Signal from "../global/event/Signal";
import HallWebSocket from "../network/HallWebSocket";
import { com } from "../network/pb/socket";
import { ComUtil } from "../utils/ComUtil";
import { SocketDataUtil } from "../utils/SocketDataUtil";

/**
 * 资产管理类
 * 负责处理资产相关的请求和数据管理
 */
class AssetManager {
    private static _instance: AssetManager;
    private _tokenData: TokenData[];

    /**
     * 获取单例
     */
    public static getInstance(): AssetManager {
        if (!this._instance) {
            this._instance = new AssetManager();
        }
        return this._instance;
    }

    /**
     * 构造函数
     */
    private constructor() {
        this.init();
    }

    /**
     * 初始化
     */
    private init(): void {
        // 监听资产查询消息
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_QUERY_TOKEN, this, this.onRequestInfo);
    }

    /**
     * 销毁
     */
    public destroy(): void {
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_QUERY_TOKEN, this, this.onRequestInfo);
        AssetManager._instance = null;
    }

    /**
     * 请求资产信息
     */
    public requestCoinInfo(): void {
        const cmdId = com.snake.socket.MessageType.MSG_QUERY_TOKEN;
        HallWebSocket.send(cmdId);
    }
    /**
     * 请求资产信息
     */
    public firstRequestCoinInfo(): void {
        if (!this._tokenData) {
            this.requestCoinInfo();
        }
    }

    /**
     * 获取资产信息
     */
    private onRequestInfo(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_QUERY_TOKEN = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_QUERY_TOKEN);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            // 解析成可用的object格式
            console.log(msgBody);
            const parsedTokens = ComUtil.parseTokenData(msgBody.token);
            // 保存数据
            this._tokenData = parsedTokens;
            // 发送余额更新事件
            Signal.event(GameEvent.UPDATE_TOKEN_BALANCE, [parsedTokens]);
        }
    }

    /**
     * 获取当前资产数据
     * @returns 资产数据数组
     */
    public getTokenData(): TokenData[] {
        return this._tokenData;
    }

    /**
     * 通过symbolId获取特定的代币数据
     * @param symbolId 代币符号ID
     * @returns 代币数据或undefined
     */
    public getTokenDataBySyId(symbolId: number): TokenData | undefined {
        if (!this._tokenData || this._tokenData.length === 0) {
            console.warn("未查到缓存的资产信息,请先获取");
            return undefined;
        }
        return this._tokenData.find((item) => item.symbolId === symbolId);
    }

    /**
     * 计算资产总额
     * @returns 计算后的总额（USDT）
     */
    public calculateTotalValue(): number {
        try {
            return this._tokenData.reduce((acc, item) => {
                const amount = item.balance;
                const price = item.price;
                if (isNaN(amount) || isNaN(price)) return acc;
                return acc + amount * price;
            }, 0);
        } catch (error) {
            console.error("计算资产总额时发生错误:", error);
            return 0;
        }
    }
}
export default AssetManager.getInstance();
